<script setup lang="ts">const range=ref(7);const {data,pending,error}=await useFetch<any>(()=>'/api/progress?days='+range.value,{watch:[range]})</script>
<template><div><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm text-emerald-700">YOUR TRENDS</p><h1 class="mt-1 text-3xl font-semibold">Progress</h1><p class="mt-2 text-stone-500">See the consistency behind your results.</p></div><select v-model.number="range" class="rounded-xl border bg-white px-4 py-3 text-sm"><option :value="7">7 days</option><option :value="30">30 days</option><option :value="365">Entire challenge</option></select></div><p v-if="error" class="mt-6 rounded-xl bg-amber-50 p-4 text-sm">Sign in and connect your database to view progress.</p><div v-else-if="pending" class="mt-7 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><div v-for="i in 4" :key="i" class="h-32 animate-pulse rounded-2xl bg-stone-200"/></div><template v-else-if="data?.days?.length"><section class="mt-7 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><StatCard label="Avg. calories" :value="Math.round(data.averages.calories)"/><StatCard label="Avg. protein" :value="Math.round(data.averages.protein)+'g'"/><StatCard label="Current streak" :value="data.winterArc.currentStreak+' days'"/><StatCard label="Habit completion" :value="data.winterArc.habitCompletion+'%'"/></section><section class="mt-6 rounded-2xl bg-white p-6"><h2 class="font-semibold">Calories by day</h2><div class="mt-6 flex h-56 items-end gap-2 border-b"> <div v-for="d in data.days" :key="d.date" class="flex flex-1 flex-col items-center justify-end gap-2"><div class="w-full max-w-10 rounded-t-lg bg-emerald-500/80" :title="d.calories+' kcal'" :style="{height:Math.max(d.calories/(data.averages.calories||1)*45,3)+'%'}"/><span class="text-[10px] text-stone-400">{{new Date(d.date+'T00:00:00').toLocaleDateString('en',{weekday:'narrow'})}}</span></div></div><p class="mt-3 text-xs text-stone-400">Daily calories from logged meals.</p></section></template><div v-else class="mt-7 rounded-2xl bg-white p-10 text-center"><p class="text-3xl">📊</p><h2 class="mt-3 font-semibold">Not enough data yet</h2><p class="mt-1 text-sm text-stone-500">Keep tracking to see your progress.</p></div></div></template>
